inputs.script:
$ErrorActionPreference = 'Continue'

$packageRoot = "$(TEST_PACKAGE_ROOT)"
$resultsDirectory = "$(StageResultsDirectory)"
$stageKey = "$(StageKey)"
if ([string]::IsNullOrWhiteSpace($packageRoot) -or -not (Test-Path -LiteralPath $packageRoot -PathType Container)) {
    Write-Warning 'The prepared test package is unavailable, so report/zip publishing is skipped.'
    exit 0
}

$resultsRoot = Join-Path $packageRoot $resultsDirectory
$evidenceRoot = Join-Path $resultsRoot 'Artifacts'
$scenarioResult = $null
if ((Test-Path -LiteralPath $reportScript -PathType Leaf) -and $null -ne $scenarioResult) {
    try {
        & $reportScript -ResultsDirectory $resultsDirectory
        if ($LASTEXITCODE -ne 0) { throw "Report generator exited with code $LASTEXITCODE." }
        $reportRoot = Join-Path $resultsRoot 'ConsolidatedReport'
        foreach ($file in @('report.html','log.html','summary.json','output.xml')) {
            $full = Join-Path $reportRoot $file
            if (Test-Path -LiteralPath $full -PathType Leaf) {
                if ($file -eq 'report.html') { Write-Host "##vso[task.uploadsummary]$full" }
                Write-Host "##vso[task.uploadfile]$full"
            }
        }
    }
    catch { Write-Warning "Consolidated report generation failed: $($_.Exception.Message)" }
}

if (Test-Path -LiteralPath $resultsRoot -PathType Container) {
    $artifactDir = Join-Path $packageRoot 'StageArtifacts'
    New-Item -ItemType Directory -Path $artifactDir -Force | Out-Null
    $zipPath = Join-Path $artifactDir ("{0}-TestResults.zip" -f $stageKey)
    if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
    Compress-Archive -Path (Join-Path $resultsRoot '*') -DestinationPath $zipPath -CompressionLevel Optimal
    Write-Host "##vso[task.uploadfile]$zipPath"
}
exit 0

